import {EXPEDITION_SPEC,expeditionProject,expeditionUnproject} from './campaign-cave-expedition.js';
// The world blueprint and depletion ledger never belong to this evictable cache.
export class ChunkStream{
 constructor(world,{createJob,requestChunk=null,dispose=()=>{},pendingBytes=()=>0,now=()=>performance.now(),limit=EXPEDITION_SPEC.chunkCache,rasterBudget=64*1048576}={}){this.world=world;this.createJob=createJob;this.requestChunk=requestChunk;this.dispose=dispose;this.pendingBytes=pendingBytes;this.now=now;this.limit=limit;this.rasterBudget=rasterBudget;this.cache=new Map();this.queue=[];this.required=new Set();this.desired=new Set();this.inFlight=new Set();this.deferred=new Set();this.epoch=0;this.workerFailures=0;this.completed=0;this.cancelled=0;this.maxEntries=0;this.units=0;this.evictions=0;this.maxUnitMs=0;this.maxPumpMs=0;this.windowId='';}
 bounds(view,padding=0){const points=[];for(const dx of [-view.width/(2*view.zoom),view.width/(2*view.zoom)])for(const dy of [-view.height/(2*view.zoom)-40,view.height/(2*view.zoom)+45])points.push(expeditionUnproject(view.center[0]+dx,view.center[1]+dy));return {minX:Math.max(0,Math.floor((Math.min(...points.map(p=>p.x))-padding)/16)),maxX:Math.min(Math.ceil(this.world.cols/16)-1,Math.floor((Math.max(...points.map(p=>p.x))+padding)/16)),minY:Math.max(0,Math.floor((Math.min(...points.map(p=>p.y))-padding)/16)),maxY:Math.min(Math.ceil(this.world.rows/16)-1,Math.floor((Math.max(...points.map(p=>p.y))+padding)/16))};}
 keys(bounds){const keys=[];for(let y=bounds.minY;y<=bounds.maxY;y++)for(let x=bounds.minX;x<=bounds.maxX;x++)keys.push(`${x},${y}`);return keys;}
 setView(view,{ahead={x:0,y:0}}={}){
  const required=this.keys(this.bounds(view,1)),base=this.keys(this.bounds(view,16)),padded={...view,center:[view.center[0]+ahead.x*22*24+ahead.y*2*24,view.center[1]+ahead.y*16*24]},near=this.keys(this.bounds(padded,16)),windowId=required.join('|')+';'+base.join('|')+';'+near.join('|'),changed=windowId!==this.windowId;if(!changed&&[...this.desired].every(key=>this.cache.has(key)||this.deferred.has(key)))return;if(changed)this.deferred.clear();this.windowId=windowId;this.required=new Set(required);this.baseKeys=new Set(base);this.desired=new Set([...required,...base,...near]);
  // Keep a full border for direction changes, plus 24 cells along current travel.
  const target=expeditionUnproject(...view.center),priority=key=>{const [x,y]=key.split(',').map(Number);return (!this.desired.has(key)?100000:this.required.has(key)?0:this.baseKeys.has(key)?1000:2000)+Math.hypot(x*16+8-target.x,y*16+8-target.y);};this.priority=priority;
  // Completed and partially built chunks remain in the bounded LRU on turns.
  // In-flight worker jobs finish once, rather than restarting at every boundary.
  this.queue=this.queue.filter(entry=>this.desired.has(entry.key));
  for(const key of [...this.desired].sort((a,b)=>priority(a)-priority(b))){if(this.deferred.has(key)&&!this.required.has(key)&&!this.baseKeys.has(key))continue;let entry=this.cache.get(key);if(!entry){entry={key,ready:false,job:null,value:null};this.cache.set(key,entry);}else{this.cache.delete(key);this.cache.set(key,entry);}if(!entry.ready&&!this.inFlight.has(entry)&&!this.queue.includes(entry))this.queue.push(entry);}
  this.queue.sort((a,b)=>priority(a.key)-priority(b.key));this.evict();this.maxEntries=Math.max(this.maxEntries,this.cache.size);if(this.cache.size>this.limit)throw Error('Visible prefetch exceeds cache budget');
 }
 discard(key,entry){this.dispose(entry.value);if(entry.job){entry.job.return?.();this.cancelled++;}this.cache.delete(key);this.queue=this.queue.filter(e=>e!==entry);this.evictions++;}
 evict(){for(const [key,entry]of this.cache){if(this.cache.size<=this.limit)break;if(!this.desired.has(key)&&!this.inFlight.has(entry))this.discard(key,entry);}}
 rasterBytes(){return [...this.cache.values()].reduce((n,e)=>n+(e.value?.rasterBytes||0),0)+this.pendingBytes();}
 enforceRasterBudget(){let bytes=this.rasterBytes();if(bytes<=this.rasterBudget)return;const choices=[...this.cache].filter(([key,e])=>!this.inFlight.has(e)&&!this.required.has(key)&&!this.baseKeys?.has(key)).sort((a,b)=>this.priority(b[0])-this.priority(a[0]));for(const [key,entry]of choices){if(bytes<=this.rasterBudget)break;this.discard(key,entry);if(this.desired.has(key))this.deferred.add(key);bytes=this.rasterBytes();}if(bytes>this.rasterBudget)throw Error('Camera exceeds inspection raster budget');}
 launch(entry){
  const epoch=this.epoch,promise=this.requestChunk?.(entry.key);if(!promise)return false;this.inFlight.add(entry);this.queue=this.queue.filter(e=>e!==entry);
  Promise.resolve(promise).then(value=>{this.inFlight.delete(entry);if(epoch!==this.epoch||this.cache.get(entry.key)!==entry){this.dispose(value);return;}entry.ready=true;entry.value=value;this.completed++;this.enforceRasterBudget();this.evict();}).catch(error=>{this.inFlight.delete(entry);if(epoch!==this.epoch||this.cache.get(entry.key)!==entry)return;if(entry.ready){this.error=error;return;}this.workerFailures++;this.requestChunk=null;if(this.desired.has(entry.key)&&!this.queue.includes(entry)){this.queue.push(entry);this.queue.sort((a,b)=>this.priority(a.key)-this.priority(b.key));}});return true;
 }
 pump({budgetMs=EXPEDITION_SPEC.workBudgetMs,maxUnits=EXPEDITION_SPEC.maxWorkUnits}={}){
  if(this.error)throw this.error;const start=this.now();let units=0;while(this.queue.length&&units<maxUnits&&(units===0||this.now()-start<budgetMs)){const entry=this.queue[0],before=this.now();if(this.requestChunk&&!entry.job){if(this.inFlight.size>=2)break;if(this.launch(entry)){units++;this.units++;continue;}}if(!entry.job)entry.job=this.createJob(entry.key);const result=entry.job.next(),unitMs=this.now()-before;if(unitMs>this.maxUnitMs){this.maxUnitMs=unitMs;this.worstUnit={key:entry.key,label:result.value?.label||'complete',ms:unitMs};}units++;this.units++;if(result.done){entry.ready=true;entry.value=result.value;entry.job=null;this.queue.shift();this.completed++;}this.enforceRasterBudget();}
  const elapsed=this.now()-start;this.maxPumpMs=Math.max(this.maxPumpMs,elapsed);return {units,elapsed,remaining:this.queue.length};
 }
 readyFor(view){return this.keys(this.bounds(view,1)).every(key=>this.cache.get(key)?.ready);}
 warmFor(view){return this.keys(this.bounds(view,16)).every(key=>this.cache.get(key)?.ready);}
 visible(view){return this.keys(this.bounds(view)).map(key=>this.cache.get(key)).filter(e=>e?.ready).map(e=>e.value);}
 status(){return {entries:this.cache.size,limit:this.limit,queued:this.queue.length,inFlight:this.inFlight.size,ready:[...this.cache.values()].filter(e=>e.ready).length,maxEntries:this.maxEntries,units:this.units,completed:this.completed,cancelled:this.cancelled,workerFailures:this.workerFailures,evictions:this.evictions,maxUnitMs:this.maxUnitMs,maxPumpMs:this.maxPumpMs,worstUnit:this.worstUnit};}
 clear(){this.epoch++;for(const e of this.cache.values()){e.job?.return?.();this.dispose(e.value);}this.cache.clear();this.queue=[];this.inFlight.clear();this.deferred.clear();this.required.clear();this.desired.clear();this.windowId='';this.error=null;}
}
export function chunkCoordinates(key){const [cx,cy]=key.split(',').map(Number);return {cx,cy,minX:cx*16,maxX:cx*16+15,minY:cy*16,maxY:cy*16+15};}
export function chunkRasterBounds(key){const {minX,maxX,minY,maxY}=chunkCoordinates(key),points=[[minX,minY],[maxX,minY],[maxX,maxY],[minX,maxY]].map(p=>expeditionProject(...p));const x=Math.floor(Math.min(...points.map(p=>p[0])))-13,y=Math.floor(Math.min(...points.map(p=>p[1])))-9;return {x,y,w:Math.ceil(Math.max(...points.map(p=>p[0])))-x+14,h:Math.ceil(Math.max(...points.map(p=>p[1])))-y+10};}
